#!/usr/bin/env sh
# Seed the local development database. Idempotent. Creates a demo project.
# Uses DATABASE_URL (environment or deploy/.env) with a local psql when set,
# otherwise the compose "db" service. SMTP credentials are secrets generated by
# the server, create one in the UI (Settings) or via the API.
set -eu

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
ENV_FILE="$ROOT/deploy/.env"
[ -f "$ENV_FILE" ] && { set -a; . "$ENV_FILE"; set +a; }

SQL="
INSERT INTO instance_settings (key, value)
VALUES ('instance_name', 'Sandpost (dev)')
ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
INSERT INTO projects (slug, name) VALUES ('demo', 'Demo')
ON CONFLICT (slug) DO NOTHING;
"

if [ -n "${DATABASE_URL:-}" ]; then
	printf '%s\n' "$SQL" | psql -v ON_ERROR_STOP=1 "$DATABASE_URL"
else
	COMPOSE="docker compose -f $ROOT/deploy/docker-compose.yml"
	[ -f "$ENV_FILE" ] && COMPOSE="$COMPOSE --env-file $ENV_FILE"
	printf '%s\n' "$SQL" | $COMPOSE exec -T db psql -v ON_ERROR_STOP=1 -U sandpost -d sandpost
fi
echo "seed complete"
